#!/usr/bin/env python3
"""Applies the native permissions and background modes the app needs to the platform folders generated by `flutter create`.
Idempotent: safe to run several times. Usage: python3 tool/configure_native.py [mobile_dir]"""
import plistlib
import re
import sys
from pathlib import Path

ANDROID_PERMISSIONS = [
    "android.permission.INTERNET",                      # not in the release manifest generated by flutter create
    "android.permission.ACCESS_NETWORK_STATE",
    "android.permission.ACCESS_FINE_LOCATION",
    "android.permission.ACCESS_COARSE_LOCATION",
    "android.permission.ACCESS_BACKGROUND_LOCATION",    # student tracking while the app is in the background (see store/ justification)
    "android.permission.FOREGROUND_SERVICE",
    "android.permission.FOREGROUND_SERVICE_LOCATION",
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.CAMERA",                        # QR scan (cash payments)
    "android.permission.USE_BIOMETRIC",
]
IOS_STRINGS = {
    "NSLocationWhenInUseUsageDescription": "ÉcoleManager partage ta position avec tes parents uniquement s'ils l'ont autorisé. / Your location is shared with your parents only if they allowed it.",
    "NSLocationAlwaysAndWhenInUseUsageDescription": "Pendant les heures d'école, ta position est envoyée même quand l'application est fermée, uniquement avec l'accord de tes parents. / During school hours your location is sent even in the background, only with your parents' consent.",
    "NSLocationAlwaysUsageDescription": "Suivi de position en arrière-plan avec consentement parental. / Background location with parental consent.",
    "NSCameraUsageDescription": "La caméra sert à scanner le code QR de paiement en espèces. / The camera is used to scan the cash payment QR code.",
    "NSFaceIDUsageDescription": "Déverrouillage biométrique optionnel de l'application. / Optional biometric unlock.",
}
IOS_BACKGROUND_MODES = ["location", "remote-notification"]


def patch_android(root: Path) -> bool:
    f = root / "android/app/src/main/AndroidManifest.xml"
    if not f.exists():
        return False
    xml = f.read_text(encoding="utf-8")
    missing = [p for p in ANDROID_PERMISSIONS if f'android:name="{p}"' not in xml]
    if missing:
        block = "".join(f'    <uses-permission android:name="{p}"/>\n' for p in missing)
        xml = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + block, xml, count=1)
        f.write_text(xml, encoding="utf-8")
    return True


NETWORK_CONFIG = """<?xml version="1.0" encoding="utf-8"?>
<!-- model_viewer_plus serves its viewer page from a local http server: cleartext is allowed for the device itself ONLY. Everything else stays https. -->
<network-security-config>
    <base-config cleartextTrafficPermitted="false"/>
    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="false">localhost</domain>
        <domain includeSubdomains="false">127.0.0.1</domain>
    </domain-config>
</network-security-config>
"""
AR_QUERIES = """    <queries>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="https"/></intent>
    </queries>
"""


def patch_android_xr(root: Path) -> bool:
    """3D/AR viewer (ARCore Scene Viewer through model_viewer_plus): local-only cleartext and the intent query needed to launch Scene Viewer."""
    f = root / "android/app/src/main/AndroidManifest.xml"
    if not f.exists():
        return False
    res = root / "android/app/src/main/res/xml"
    res.mkdir(parents=True, exist_ok=True)
    (res / "network_security_config.xml").write_text(NETWORK_CONFIG, encoding="utf-8")
    xml = f.read_text(encoding="utf-8")
    if "android:networkSecurityConfig" not in xml:
        xml = re.sub(r"<application", '<application android:networkSecurityConfig="@xml/network_security_config"', xml, count=1)
    if "<queries>" not in xml:
        xml = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + AR_QUERIES, xml, count=1)
    f.write_text(xml, encoding="utf-8")
    return True


SIGNING_KTS_HEAD = """import java.io.FileInputStream
import java.util.Properties

val keystoreProperties = Properties().apply {
    val f = rootProject.file("key.properties")      // written by CI from secrets or by the publisher locally; never committed (.gitignore)
    if (f.exists()) load(FileInputStream(f))
}

"""
SIGNING_KTS_BLOCK = """    signingConfigs {
        create("release") {
            if (keystoreProperties.containsKey("storeFile")) {
                keyAlias = keystoreProperties["keyAlias"] as String
                keyPassword = keystoreProperties["keyPassword"] as String
                storeFile = file(keystoreProperties["storeFile"] as String)
                storePassword = keystoreProperties["storePassword"] as String
            }
        }
    }

"""
SIGNING_GROOVY_HEAD = """def keystoreProperties = new Properties()
def keystorePropertiesFile = rootProject.file('key.properties')   // written by CI from secrets or by the publisher locally; never committed (.gitignore)
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}

"""
SIGNING_GROOVY_BLOCK = """    signingConfigs {
        release {
            if (keystoreProperties['storeFile']) {
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
                storeFile file(keystoreProperties['storeFile'])
                storePassword keystoreProperties['storePassword']
            }
        }
    }

"""


def patch_android_signing(root: Path, application_id: str | None = None) -> bool:
    """Release signing from key.properties (the keystore is generated by the publisher and never committed); falls back to debug signing when absent so test builds still work.
    Optionally sets the applicationId."""
    for name in ("build.gradle.kts", "build.gradle"):
        f = root / "android/app" / name
        if not f.exists():
            continue
        g = f.read_text(encoding="utf-8"); kts = name.endswith(".kts")
        if "key.properties" not in g:
            if kts:
                g = SIGNING_KTS_HEAD + g
                g = re.sub(r"(\nandroid \{\n)", lambda m: m.group(1) + SIGNING_KTS_BLOCK, g, count=1)
                g = re.sub(r'signingConfig = signingConfigs.getByName\("debug"\)', 'signingConfig = if (keystoreProperties.containsKey("storeFile")) signingConfigs.getByName("release") else signingConfigs.getByName("debug")', g, count=1)
            else:
                g = SIGNING_GROOVY_HEAD + g
                g = re.sub(r"(\nandroid \{\n)", lambda m: m.group(1) + SIGNING_GROOVY_BLOCK, g, count=1)
                g = re.sub(r"signingConfig signingConfigs.debug", "signingConfig keystoreProperties['storeFile'] ? signingConfigs.release : signingConfigs.debug", g, count=1)
        if application_id:
            g = re.sub(r'applicationId\s*=?\s*"[^"]*"', ('applicationId = "%s"' if kts else 'applicationId "%s"') % application_id, g, count=1)
        f.write_text(g, encoding="utf-8")
        return True
    return False


ENTITLEMENTS = {"aps-environment": "production"}   # push notifications; background location is an Info.plist mode, not an entitlement


def patch_ios_entitlements(root: Path, bundle_id: str | None = None) -> bool:
    """Writes Runner.entitlements (push) and references it from the Runner target; optionally sets the bundle identifier."""
    runner = root / "ios/Runner"; proj = root / "ios/Runner.xcodeproj/project.pbxproj"
    if not runner.exists() or not proj.exists():
        return False
    (runner / "Runner.entitlements").write_bytes(plistlib.dumps(ENTITLEMENTS))
    txt = proj.read_text(encoding="utf-8")
    def add(m):
        if m.group(1).endswith("RunnerTests"):
            return m.group(0)
        ident = bundle_id or m.group(1)
        return f"PRODUCT_BUNDLE_IDENTIFIER = {ident};" + ("" if "CODE_SIGN_ENTITLEMENTS" in txt[m.end():m.end() + 120] else "\n\t\t\t\tCODE_SIGN_ENTITLEMENTS = Runner/Runner.entitlements;")
    txt = re.sub(r"PRODUCT_BUNDLE_IDENTIFIER = ([^;]+);", add, txt)
    proj.write_text(txt, encoding="utf-8")
    return True


MIN_SDK = 23   # firebase_messaging / ARCore-capable devices; Flutter's default (21) is refused by the Firebase libraries
GOOGLE_SERVICES_VERSION = "4.4.2"


def patch_android_min_sdk(root: Path) -> bool:
    for name in ("build.gradle.kts", "build.gradle"):
        f = root / "android/app" / name
        if not f.exists():
            continue
        g = f.read_text(encoding="utf-8")
        g2 = re.sub(r"minSdk(Version)?(\s*=\s*|\s+)flutter\.minSdkVersion", lambda m: f"minSdk{m.group(1) or ''}{m.group(2)}{MIN_SDK}", g)
        if g2 != g:
            f.write_text(g2, encoding="utf-8")
        return True
    return False


def patch_android_firebase(root: Path) -> bool:
    """Applies the Google services plugin ONLY when the publisher's google-services.json is present (never committed). Without it the app builds and push stays in sandbox."""
    if not (root / "android/app/google-services.json").exists():
        return False
    for sname in ("settings.gradle.kts", "settings.gradle"):
        sf = root / "android" / sname
        if sf.exists():
            t = sf.read_text(encoding="utf-8")
            if "com.google.gms.google-services" not in t:
                kts = sname.endswith(".kts")
                line = f'    id("com.google.gms.google-services") version "{GOOGLE_SERVICES_VERSION}" apply false\n' if kts else f'    id "com.google.gms.google-services" version "{GOOGLE_SERVICES_VERSION}" apply false\n'
                t = re.sub(r"(\n[ \t]*id\(?\s*[\"']com\.android\.application[\"']\)?[^\n]*\n)", lambda m: m.group(1) + line, t, count=1)
                sf.write_text(t, encoding="utf-8")
            break
    for name in ("build.gradle.kts", "build.gradle"):
        f = root / "android/app" / name
        if f.exists():
            g = f.read_text(encoding="utf-8")
            if "com.google.gms.google-services" not in g:
                line = '    id("com.google.gms.google-services")\n' if name.endswith(".kts") else '    id "com.google.gms.google-services"\n'
                g = re.sub(r"(plugins \{\n)", lambda m: m.group(1) + line, g, count=1)
                f.write_text(g, encoding="utf-8")
            return "com.google.gms.google-services" in g
    return False


COMPILE_SDK = 36
ROOT_KTS = """// ecole-compile-sdk: plugin libraries compiled against an old SDK (e.g. flutter_appauth) fail the AAR metadata check; compile every library module against a recent SDK.
subprojects {
    val raise = { p: Project ->
        val ext = p.extensions.findByName("android")
        if (ext != null) { try { ext.javaClass.getMethod("setCompileSdkVersion", Int::class.javaPrimitiveType).invoke(ext, %d) } catch (_: Exception) { } }
    }
    if (state.executed) raise(this) else afterEvaluate { raise(this) }
}

""" % COMPILE_SDK
ROOT_GROOVY = """// ecole-compile-sdk: plugin libraries compiled against an old SDK (e.g. flutter_appauth) fail the AAR metadata check; compile every library module against a recent SDK.
subprojects {
    def raise = { p -> if (p.hasProperty('android')) { try { p.android.compileSdkVersion %d } catch (ignored) { } } }
    if (state.executed) { raise(it) } else { afterEvaluate { raise(it) } }
}

""" % COMPILE_SDK


def patch_android_root_compile_sdk(root: Path) -> bool:
    for name, snippet in (("build.gradle.kts", ROOT_KTS), ("build.gradle", ROOT_GROOVY)):
        f = root / "android" / name
        if not f.exists():
            continue
        g = f.read_text(encoding="utf-8")
        if "ecole-compile-sdk" not in g:
            g = g.replace("allprojects", snippet + "allprojects", 1) if "allprojects" in g else snippet + g
            f.write_text(g, encoding="utf-8")
        return True
    return False


def patch_oidc_redirect(root: Path, scheme: str) -> dict:
    """Custom-scheme redirect used by AppAuth for the OIDC + PKCE sign-in (Keycloak client `ecolemanager-mobile`, redirect `<scheme>:/oauthredirect`)."""
    done = {"android": False, "ios": False}
    for name in ("build.gradle.kts", "build.gradle"):
        f = root / "android/app" / name
        if not f.exists():
            continue
        g = f.read_text(encoding="utf-8")
        if "appAuthRedirectScheme" not in g:
            line = f'        manifestPlaceholders["appAuthRedirectScheme"] = "{scheme}"\n' if name.endswith(".kts") else f"        manifestPlaceholders = [appAuthRedirectScheme: '{scheme}']\n"
            g = re.sub(r"(\n\s*defaultConfig \{\n)", lambda m: m.group(1) + line, g, count=1)
            f.write_text(g, encoding="utf-8")
        done["android"] = "appAuthRedirectScheme" in g
        break
    p = root / "ios/Runner/Info.plist"
    if p.exists():
        d = plistlib.loads(p.read_bytes())
        types = d.get("CFBundleURLTypes", [])
        if not any(scheme in t.get("CFBundleURLSchemes", []) for t in types):
            types.append({"CFBundleURLName": "oidc-redirect", "CFBundleURLSchemes": [scheme]})
            d["CFBundleURLTypes"] = types; p.write_bytes(plistlib.dumps(d))
        done["ios"] = True
    return done


def patch_app_name(root: Path, name: str) -> None:
    m = root / "android/app/src/main/AndroidManifest.xml"
    if m.exists():
        m.write_text(re.sub(r'android:label="[^"]*"', f'android:label="{name}"', m.read_text(encoding="utf-8"), count=1), encoding="utf-8")
    f = root / "ios/Runner/Info.plist"
    if f.exists():
        d = plistlib.loads(f.read_bytes()); d["CFBundleDisplayName"] = name; d["CFBundleName"] = name; f.write_bytes(plistlib.dumps(d))


def patch_ios(root: Path) -> bool:
    f = root / "ios/Runner/Info.plist"
    if not f.exists():
        return False
    data = plistlib.loads(f.read_bytes())
    data.update(IOS_STRINGS)
    data["io.flutter.embedded_views_preview"] = True          # WebView-based 3D/AR viewer (AR Quick Look)
    modes = list(data.get("UIBackgroundModes", []))
    data["UIBackgroundModes"] = modes + [m for m in IOS_BACKGROUND_MODES if m not in modes]
    f.write_bytes(plistlib.dumps(data))
    return True


if __name__ == "__main__":
    base = Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    a, i = patch_android(base), patch_ios(base)
    if a:
        patch_android_xr(base)
    import os
    app_id = os.environ.get("APP_ID", "com.stonytechnologie.ecolemanager")   # working identifier until the publisher communicates the real one
    patch_android_root_compile_sdk(base); patch_android_min_sdk(base); patch_android_firebase(base)
    patch_oidc_redirect(base, os.environ.get("OIDC_REDIRECT_SCHEME", "com.ecolemanager.pro"))
    patch_android_signing(base, app_id); patch_ios_entitlements(base, app_id); patch_app_name(base, os.environ.get("APP_NAME", "ÉcoleManager Pro"))
    print(f"android={'patched' if a else 'absent'} ios={'patched' if i else 'absent'}")
    if not (a or i):
        sys.exit("no platform folder found: run `flutter create --platforms=android,ios .` first")
